"""A transparent unit-root evidence ledger, distinct from statistical significance."""
from __future__ import annotations
import base64
import gzip
import html
import json
from pathlib import Path
import pandas as pd
from stationarity_audit import LABELS,SUPPORT
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs/stationarity'


def compressed_download(name,label):
    source=OUT/name
    target=source.with_suffix(source.suffix+'.gz')
    target.write_bytes(gzip.compress(source.read_bytes(),mtime=0))
    return f'<a href="data:application/gzip;base64,{base64.b64encode(target.read_bytes()).decode()}" download="{target.name}">{html.escape(label)} · CSV.gz ↓</a>'


def build_stationarity_report():
    diagnostics=pd.read_csv(OUT/'diagnostics.csv');models=pd.read_csv(OUT/'model_assessments.csv')
    summary=json.loads((OUT/'summary.json').read_text())
    fields=['diagnostic_id','context','sector_id','sector','variable','kind','scope','start','end','n_periods','calendar_gaps','missing_values',
        'deterministic','state','label','primary_state','legacy_state','primary_adf_p','primary_kpss_p','primary_kpss_relation',
        'primary_adf_lags','primary_kpss_lags','legacy_adf_p','legacy_kpss_p']
    data={'diagnostics':json.loads(diagnostics[fields].to_json(orient='records')),'models':json.loads(models.to_json(orient='records')),'labels':LABELS}
    payload=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
    history=diagnostics[diagnostics.scope.eq('available_history')]
    growth=history[history.variable.isin(['y_short','y_yoy','y_yoy_nsa'])]
    ncompatible=int(growth.state.isin(SUPPORT).sum())
    download=' · '.join([compressed_download('diagnostics.csv','All series/window evidence'),compressed_download('tests.csv','ADF/KPSS statistics and lag choices'),
        compressed_download('model_variable_coverage.csv','Every model–variable link'),compressed_download('model_assessments.csv','Model assessments'),compressed_download('series.csv','Exact tested observations')])
    style='''*{box-sizing:border-box}body{margin:0;background:#f3f7fa;color:#15334a;font:14px/1.65 "Avenir Next","Segoe UI",Arial,sans-serif}main{max-width:1320px;padding:30px 32px;margin:auto}h1,h2{font-family:"Avenir Next Condensed",Arial,sans-serif;line-height:1.15}h1{font-size:43px}h2{font-size:29px;margin-top:34px}a{color:#1f77b4}.eyebrow{font:11px Menlo,monospace;color:#64798b;text-transform:uppercase;letter-spacing:1px}.callout{padding:17px 20px;background:#fff4e8;border-left:3px solid #c67b35;margin:24px 0}.cards{display:flex;gap:15px;flex-wrap:wrap}.card{flex:1;min-width:210px;padding:20px;background:white;border:1px solid #dbe4eb;border-radius:8px}.card strong{font-size:28px;display:block}.sub,.notes{font-size:12px;color:#64798b}.controls{display:flex;gap:15px;flex-wrap:wrap;margin:20px 0}label{font-size:12px;color:#64798b}select{display:block;font:13px inherit;color:#15334a;background:white;padding:9px;border:1px solid #dbe4eb;border-radius:5px;margin-top:5px;max-width:320px}.scroll{overflow:auto;background:white;border:1px solid #dbe4eb;border-radius:8px}.compact{border-collapse:collapse;width:100%;font-size:12px}.compact td,.compact th{padding:12px;border-bottom:1px solid #dbe4eb;text-align:left;font-variant-numeric:tabular-nums;vertical-align:top}.compact th{color:#64798b}.compact td{min-width:90px}.compact td:first-child{min-width:180px}.badge{font-size:11px;display:inline-block;padding:4px 7px;border-radius:4px;background:#fff4e8;color:#7c4a20}.badge.good{background:#e5f2ef;color:#195448}.badge.bad{background:#fbeaec;color:#943746}.downloads{font-size:12px;line-height:2}.legend{font-size:12px;max-width:1100px}footer{margin-top:35px;border-top:1px solid #dbe4eb;padding-top:20px;font-size:12px}details{margin:24px 0;border-top:1px solid #dbe4eb;padding-top:15px}summary{font-weight:600;cursor:pointer}@media(max-width:700px){main{padding:20px 16px}h1{font-size:34px}}'''
    body=f'''<main><div class="eyebrow">Singapore / Stationarity and inference</div><h1>Stationarity: checked, with unresolved cases visible.</h1>
<div class="callout"><strong>We cannot confirm that all specifications are stationary.</strong> This tab maps monthly/quarterly source-model outcomes and weather regressors, including detailed sectors, official totals, SA and NSA YoY, exact growth sensitivities, transformed weather and wind/PM2.5. The Annual analyses tab contains its own annual-frequency diagnostics. Some growth series have mixed or lag-sensitive evidence; many levels show persistence concerns. Standard ADF/KPSS tests are not run after compressing calendar gaps. Those short screened/COVID-excluded windows remain unestablished.</div>
<div class="cards"><div class="card"><strong>{len(models)}</strong>model/outcome groups mapped<span class="sub">Includes equivalent separate-series source mappings</span></div><div class="card"><strong>{len(diagnostics):,}</strong>distinct series/windows<span class="sub">Exact estimation windows and separately labelled source histories</span></div><div class="card"><strong>{ncompatible}/{len(growth)}</strong>source-history growth screens compatible<span class="sub">One-period SA and YoY SA/NSA series; overlapping panel cuts are deduplicated by unit, not averaged</span></div></div>
<h2>What the flags mean.</h2><p class="legend"><strong>Stationarity-compatible:</strong> ADF rejects a unit root and KPSS does not reject stationarity at 5%, under both lag designs. <strong>Trend-stationarity-compatible:</strong> the same result with a deterministic trend; it is not evidence of stationarity around a constant. <strong>Unit-root concern:</strong> ADF does not reject and KPSS rejects. <strong>Mixed/inconclusive:</strong> the tests disagree or neither resolves the question. <strong>Lag-sensitive:</strong> the primary and legacy designs give different evidence. <strong>Not established:</strong> gaps, insufficient continuous history, missing values or unavailable tests.</p>
<p class="notes">These ordinary zero-frequency tests provide evidence, not proof. Estimated seasonal offsets in weather/NSA series are removed while retaining the trend; this is not a seasonal-unit-root test. No cointegration or general residual-stationarity claim is made. Do not choose a transformation, exclude sectors or select a preferred coefficient merely to obtain a passing test. Levels are descriptive sensitivities. Growth estimates with unresolved Y or X evidence remain exploratory.</p>
<h2>Series evidence · choose the history and variable.</h2><p class="notes">“Available history” uses the full cached source history for that series, not necessarily a particular regression’s dates. “Exact window” uses the actual dates retained in the fitted model. Matching source-history evidence cannot clear a short or gapped model window. Multiple exact windows can exist for one sector; dates are shown.</p>
<div class="controls"><label>Economic series<select id="context"><option value="all">All</option><option value="va">VA · aggregate and sectors</option><option value="iip-monthly">Monthly IIP</option><option value="iip-quarterly">Quarterly IIP</option></select></label><label>Evidence window<select id="scope"><option value="available_history">Available source history</option><option value="pre_2020_history">Pre-2020 source history</option><option value="exact_estimation_window">Exact estimation window</option></select></label><label>Variable<select id="variable"></select></label><label>Evidence<select id="state"><option value="all">All outcomes</option><option value="supported">Compatible in both designs</option><option value="unresolved">Unresolved / unavailable</option></select></label></div>
<p class="notes" id="row-count"></p><div class="scroll"><table class="compact"><thead><tr><th>Series</th><th>Variable / dates</th><th>Periods / terms</th><th>Primary ADF p</th><th>Primary KPSS p</th><th>Primary evidence</th><th>Legacy-lag evidence</th><th>Combined screen</th></tr></thead><tbody id="diagnostics"></tbody></table></div>
<h2>Does the displayed regression clear every Y and X screen?</h2><p class="notes">For gapped calendars, “not tested” is shown rather than 0/N compatible; unavailable tests are not failed tests. The counts below require compatible tests for the outcome <em>and every weather regressor</em> on its exact estimation dates, under both designs. For panels, each unit’s Y is checked separately. This is a transparent screen, not a pretest-selected preferred model. Repeated weather values across sectors do not supply independent observations.</p><div class="controls"><label>Model family<select id="family"><option value="detailed_sector_FE_interactions_main">Main detailed-sector FE interactions</option><option value="individual_sector_time_series">Individual detailed-sector time series</option><option value="sector_interactions_and_equivalent_separate_series">Sector interactions / equivalent separate series</option><option value="national_IIP_original">Original published-total IIP</option><option value="pooled">Main panels and national regressions</option><option value="all">All model groups</option></select></label></div><p class="notes" id="model-count"></p><div class="scroll"><table class="compact"><thead><tr><th>Analysis / model</th><th>Y</th><th>Compatible Y units</th><th>Compatible Y + all X units</th><th>Assessment / use</th></tr></thead><tbody id="models"></tbody></table></div>
<details><summary>Lag choices, short samples and what remains unresolved</summary><p>Primary ADF uses AIC to select lags up to 24 monthly or eight quarterly lags, constrained by sample feasibility. Primary KPSS uses its uncapped automatic Bartlett bandwidth. The prespecified sensitivity reproduces the earlier one-year ADF cap (12/four) and caps automatic KPSS at one year. We report both and do not pick the more favourable result. Overlapping YoY growth often selects long ADF lags, so a one-year cap alone was insufficient as the only sensitivity.</p><p>At least five seasonal cycles are required. The strict wind/PM sample has 100 months or29quarters, but it is gapped; excluding2020–22 leaves66months/19quarters with larger gaps. Standard tests are not applied to an artificially compressed calendar. Full-source wind evidence uses90% coverage and is also limited by gaps; PM coverage is considered separately. The 80%-coverage regression sensitivity retains its actual observed values and is not silently rescreened at90%.</p><p>Year/season fixed effects and HAC or clustered errors do not by themselves cure nonstationarity. Marginal tests do not prove that regression residuals are stationary, that a level relationship is cointegrated, that seasonal roots are absent or that a result is causal. There is no universal “all stationary” clearance.</p></details>
<h2>How to read statistical significance now.</h2><p>Sector tables and plots show saved, unrounded p-values and explicit labels: <strong>significant at1%</strong>, <strong>significant at5%</strong>, <strong>10%only</strong>, or <strong>not significant at10%</strong>. Filled forest dots mark p&lt;0.05 and open dots mark p≥0.05; text provides the same distinction. A “10%only” result is not significant at5%. Stars are*** p&lt;0.01,** p&lt;0.05,* p&lt;0.10. These are nominal pointwise tests unless a column explicitly says Holm-adjusted. A significant sector slope is not itself a significant difference from another sector; use the joint/pairwise tests for that question.</p><p class="notes">Reported p-values remain those from the labelled sector-CR1 or calendar-HAC covariance. No observations or coefficients were changed to improve significance or pass a unit-root screen. Evidence flags accompany the results rather than treating the nominal p-value as specification validation.</p>
<div class="downloads">{download}</div><footer><a href="heat_economy.html">Complete tabbed results</a> · <a href="granular_va.html">Detailed VA</a> · <a href="manufacturing_detail.html">Manufacturing</a> · <a href="sector_heterogeneity.html">Sector interactions and comparisons</a><p>Primary test documentation: <a href="https://www.statsmodels.org/stable/generated/statsmodels.tsa.stattools.adfuller.html">Statsmodels ADF</a> · <a href="https://www.statsmodels.org/stable/generated/statsmodels.tsa.stattools.kpss.html">Statsmodels KPSS</a>. Full methodological review and independent verification are embedded under Methods & sources.</p></footer></main>'''
    # Keep typography readable in prose generated from compact statistical labels.
    for a,b in [('or29','or 29'),('excluding2020','excluding 2020'),('leaves66','leaves 66'),('coverage90','coverage 90'),('at90','at 90'),('at1%','at 1%'),('at5%','at 5%'),('at10%','at 10%'),('10%only','10% only'),('are***','are ***'),(',**',', **'),(',*',', *')]:body=body.replace(a,b)
    script='''const D=JSON.parse(document.getElementById('stationarity-data').textContent),E=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const compatible=s=>['stationarity-compatible','trend-stationarity-compatible'].includes(s),p=v=>v==null?'Unavailable':v<.001?'<0.001':Number(v).toFixed(3);function badge(s){return `<span class="badge ${compatible(s)?'good':s==='unit-root-concern'?'bad':''}">${safe(D.labels[s]||s||'Unavailable')}</span>`;}const variables=[...new Set(D.diagnostics.map(r=>r.variable))];E('variable').innerHTML=variables.map(v=>`<option value="${v}">${safe(v)}</option>`).join('');E('variable').value='y_short';function render(){const rows=D.diagnostics.filter(r=>(E('context').value==='all'||r.context===E('context').value)&&r.scope===E('scope').value&&r.variable===E('variable').value&&(E('state').value==='all'||(E('state').value==='supported'?compatible(r.state):!compatible(r.state))));E('row-count').textContent=`${rows.length} matching series/window entries. p-values are unavailable when tests were not run.`;E('diagnostics').innerHTML=rows.map(r=>`<tr data-diagnostic-id="${r.diagnostic_id}"><td>${safe(r.sector)}<span class="sub"><br>${safe(r.context)}</span></td><td>${safe(r.variable)}<span class="sub"><br>${r.start}–${r.end}</span></td><td>${r.n_periods}<span class="sub"><br>${r.deterministic==='ct'?'Constant + trend':'Constant'}<br>${r.calendar_gaps} calendar gaps; ${r.missing_values} missing</span></td><td>${safe(p(r.primary_adf_p))}<span class="sub"><br>${r.primary_adf_lags??'—'} lags</span></td><td>${safe((r.primary_kpss_relation||'')+p(r.primary_kpss_p))}<span class="sub"><br>${r.primary_kpss_lags??'—'} lags</span></td><td>${badge(r.primary_state)}</td><td>${badge(r.legacy_state)}</td><td>${badge(r.state)}</td></tr>`).join('');const models=D.models.filter(r=>(E('context').value==='all'||r.context===E('context').value)&&(E('family').value==='all'||r.family===E('family').value));E('model-count').textContent=`${models.length} model/outcome groups; all unit-level links are in the download.`;E('models').innerHTML=models.map(r=>`<tr><td>${safe(r.context)} · ${safe(r.model)}<span class="sub"><br>${safe(r.source_csv)}</span></td><td>${safe(r.outcome)}</td><td>${r.any_calendar_gaps?'Not tested · calendar gaps':r.compatible_y_units+'/'+r.n_units}</td><td>${r.any_calendar_gaps?'Not established · tests unavailable':r.compatible_all_variables_units+'/'+r.n_units}</td><td>${safe(r.assessment)}<span class="sub"><br>${safe(r.analysis_role)}</span></td></tr>`).join('');}document.querySelectorAll('select').forEach(x=>x.addEventListener('change',render));render();'''
    path=ROOT/'outputs/stationarity.html'
    path.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stationarity audit · Heat and the Singapore economy</title><style>'+style+'</style></head><body>'+body+'<script id="stationarity-data" type="application/json">'+payload+'</script><script>'+script+'</script></body></html>')
    print(f'Wrote stationarity.html ({path.stat().st_size:,} bytes)')
    return path

if __name__=='__main__':build_stationarity_report()
